import { z } from 'zod'
import {
  MOBILE_WEB_BUNDLE_CHUNK_BYTES,
  MOBILE_WEB_BUNDLE_RANGE_BYTES,
  MOBILE_WEB_BUNDLE_RANGE_MAX_DATA_BASE64_LENGTH
} from '../../../src/shared/mobile-web-bundle/bundle-rpc-contract'
import {
  computeMobileWebBundleId,
  MobileWebBundleAssetPathSchema,
  MOBILE_WEB_BUNDLE_MAX_ASSETS,
  MOBILE_WEB_BUNDLE_MAX_ASSET_BYTES,
  MOBILE_WEB_BUNDLE_MAX_ROUTE_GRANTS,
  MOBILE_WEB_BUNDLE_MAX_ROUTES,
  MOBILE_WEB_BUNDLE_MAX_TOTAL_BYTES,
  SHA256_PATTERN
} from '../../../src/shared/mobile-web-bundle/manifest-contract'

// Hoisted, never built inside a reader: a schema constructed per parse cost 2275 ns against 156 ns
// for the same shape hoisted (#21311).
//
// Loose where the host contract is strict, and required only where this client reads. The host's
// own schemas describe what it produces and stay `.strict()`; a phone that rejected an unknown
// member would turn a later optional field into a released-client break instead of the Rule 1
// addition `docs/reference/remote-wire-compatibility.md` allows.

/** Base64 of one chunk, bounded by the same arithmetic as `skill-upload-session-contract.ts`, so a
 *  host that overshoots is refused at the boundary instead of at reassembly. */
const MAX_DATA_BASE64_LENGTH = Math.ceil(MOBILE_WEB_BUNDLE_CHUNK_BYTES / 3) * 4 + 8

/** A screen the desktop asks this shell to render from the bundle. Optional, because a desktop
 *  older than the field sends none, and then no route is served. Loose for the same reason the
 *  manifest is: a grant name this build does not know is not a reason to refuse a bundle, only that
 *  one route.
 *
 *  `optionalGrants` is read so this build can honour it, and typed here only — the host's own
 *  schema is where its grammar and the ceiling over the union live. A shell without this line still
 *  receives the key, because loose passes unknown members through rather than stripping them; what
 *  such a shell lacks is a policy that reads it, so it serves the route on `grants` alone. The
 *  member that must not travel on from here is the whole entry: `BridgePageRouteGrantsSchema` is
 *  `.strict()`, so `routeViewOf` builds the pairs it publishes rather than forwarding these. */
const pageRouteSchema = z.object({
  pathname: z.string().min(1).max(255),
  grants: z.array(z.string().min(1).max(64)).max(MOBILE_WEB_BUNDLE_MAX_ROUTE_GRANTS),
  optionalGrants: z
    .array(z.string().min(1).max(64))
    .max(MOBILE_WEB_BUNDLE_MAX_ROUTE_GRANTS)
    .optional(),
  // A value this build cannot read is no declaration, never a refused bundle.
  canOwnHostArea: z.boolean().optional().catch(undefined)
})

const assetSchema = z.looseObject({
  path: MobileWebBundleAssetPathSchema,
  sha256: z.string().regex(SHA256_PATTERN),
  byteLength: z.number().int().nonnegative().max(MOBILE_WEB_BUNDLE_MAX_ASSET_BYTES),
  contentType: z.string().min(1)
})

/** Everything the fetch reads: the id it caches under, the assets it pages, and the entry it will
 *  later load, plus the protocol window the update wall compares against the host.
 *  `desktopVersion` still passes through untyped; nothing reads it yet.
 *
 *  `schemaVersion` is read as a number, not pinned to the one this shell knows: refusing it here
 *  would fail the parse before `evaluateMobileWebBundleCompat` could name the shell as too old, and
 *  an unreadable schema is a wall to show, not a shape to guess at. The manifest stays closed in
 *  both directions on the host's side, where it is written.
 *
 *  Exported because the generation store re-parses the manifest it cached, and reading it back
 *  strictly after accepting it loosely would make a host's added field a forced redownload on every
 *  launch. */
export const MobileWebBundleManifestReadSchema = z
  .looseObject({
    schemaVersion: z.number().int(),
    buildId: z.string().regex(SHA256_PATTERN),
    minCompatibleRuntimeProtocolVersion: z.number().int().nonnegative(),
    runtimeProtocolVersion: z.number().int().nonnegative(),
    pageVersion: z.number().int().nonnegative().optional(),
    entrypoint: MobileWebBundleAssetPathSchema,
    totalBytes: z.number().int().nonnegative().max(MOBILE_WEB_BUNDLE_MAX_TOTAL_BYTES),
    assets: z.array(assetSchema).min(1).max(MOBILE_WEB_BUNDLE_MAX_ASSETS),
    routes: z.array(pageRouteSchema).max(MOBILE_WEB_BUNDLE_MAX_ROUTES).optional()
  })
  // Cheapest first, and the first issue returns: the build id below is the only check here that
  // hashes, and a manifest already over the allocation ceiling must not be hashed to be refused.
  .superRefine((manifest, context) => {
    // The allocation bound, and the reason it is the sum rather than `totalBytes`: the fetch
    // allocates one buffer per asset from `byteLength` and holds them all, so a manifest declaring
    // `totalBytes` 0 alongside 256 assets of 10 MiB each would pass every ceiling above and still
    // cost 2560 MiB. The host pins sum === totalBytes; this client never trusts `totalBytes` for
    // anything, so it bounds what it will actually allocate instead.
    if (
      manifest.assets.reduce((sum, asset) => sum + asset.byteLength, 0) >
      MOBILE_WEB_BUNDLE_MAX_TOTAL_BYTES
    ) {
      context.addIssue({
        code: 'custom',
        path: ['assets'],
        message: 'assets sum to more than the contract total'
      })
      return
    }
    // The same rule the host writes the manifest under, read back here rather than trusted. The id
    // is a cache key and a claim about content at once: the shell treats an id it already holds as
    // the same bytes and opens the generation on disk without paging a byte, so a stale or forged
    // id would put a bundle on screen under another one's manifest. `computeMobileWebBundleId` is
    // pure JS for exactly this reader — Metro ships no `node:crypto`.
    if (manifest.buildId !== computeMobileWebBundleId(manifest.assets)) {
      context.addIssue({
        code: 'custom',
        path: ['buildId'],
        message: 'buildId must be the content hash of the asset list'
      })
    }
  })

/** `chunkBytes` is read, never assumed: the host may shrink it without a client release. Capped at
 *  the constant because a larger value would overshoot `dataBase64` above. */
export const MobileWebBundleManifestReplySchema = z.looseObject({
  manifest: MobileWebBundleManifestReadSchema,
  chunkBytes: z.number().int().positive().max(MOBILE_WEB_BUNDLE_CHUNK_BYTES),
  /** The range grid, named only by a host that serves `mobileWeb.bundle.range`. A value this build
   *  cannot page within its `dataBase64` bound reads as absent, which keeps the fetch on chunks
   *  rather than refusing the manifest. */
  rangeBytes: z
    .number()
    .int()
    .positive()
    .max(MOBILE_WEB_BUNDLE_RANGE_BYTES)
    .optional()
    .catch(undefined)
})

/** Self-describing on purpose: `buildId`, `path` and `offset` are echoed so a reassembler cannot
 *  misplace a reply, and `sha256`/`assetByteLength` describe the whole asset rather than this
 *  window, which is what lets the fetch verify without a second index. Shared by both read replies. */
const windowHeaderFields = {
  buildId: z.string().regex(SHA256_PATTERN),
  path: MobileWebBundleAssetPathSchema,
  offset: z.number().int().nonnegative().max(MOBILE_WEB_BUNDLE_MAX_ASSET_BYTES),
  assetByteLength: z.number().int().nonnegative().max(MOBILE_WEB_BUNDLE_MAX_ASSET_BYTES),
  sha256: z.string().regex(SHA256_PATTERN),
  eof: z.boolean()
}

export const MobileWebBundleChunkReplySchema = z.looseObject({
  ...windowHeaderFields,
  dataBase64: z.string().max(MAX_DATA_BASE64_LENGTH)
})

/** The window header plus the encoding of `dataBase64`. `encoding` is read as a string, not a closed
 *  enum: an encoding this build cannot decode is a typed refusal at the decoder, which names it,
 *  rather than a reply-shape failure that names nothing. */
export const MobileWebBundleRangeReplySchema = z.looseObject({
  ...windowHeaderFields,
  encoding: z.string().min(1).max(32),
  dataBase64: z.string().max(MOBILE_WEB_BUNDLE_RANGE_MAX_DATA_BASE64_LENGTH)
})

export type MobileWebBundleManifestReply = z.output<typeof MobileWebBundleManifestReplySchema>
export type MobileWebBundleManifestRead = MobileWebBundleManifestReply['manifest']
export type MobileWebBundleAssetRead = MobileWebBundleManifestRead['assets'][number]

/**
 * Which of the app's stored keys the page may read and write, and how much of each.
 *
 * AsyncStorage's web build is `window.localStorage`, which the page does not have: Android turns
 * DOM storage off and on iOS the origin host is the session id, so anything written there is empty
 * again on the next remount. A pin that silently forgets itself is worse than one that cannot be
 * set, so the page's store is the app's, reached over the `storage` grant.
 *
 * An allowlist and not a passthrough. Everything the app keeps under `orca:` is in one namespace —
 * paired hosts, push registrations — and a page that could write any of them could rewrite state
 * the native app owns. A prefix is listed only where the key carries an id the desktop chooses; the
 * rest are exact.
 *
 * Every key here was read off a page route's own closure rather than taken from a list: a key a
 * screen reads and this file does not name is a preference that silently falls back to its default
 * inside the page and keeps working outside it, which is the failure the grant exists to end
 * (rulings-ota-c7.md ruling 7).
 */
export const PAGE_STORAGE_EXACT_KEYS = [
  /** The repo the New Workspace drawer opens on. */
  'orca:last-visited-worktree',
  /** The worktree-list sidebar's width, which `app/h/_layout.tsx` renders above every page route. */
  'orca:hostSidebarWidth',
  /** The session screen's docked panel width, dragged by `use-mobile-dock-resize.ts`. */
  'orca:hostDockWidth',
  /** The terminal accessory bar's order and visibility. */
  'orca:terminal-accessory-layout',
  /** The user's own accessory keys, which `CustomKeyModal` writes. */
  'orca:custom-accessory-keys',
  /** Whether a supported agent session opens on the terminal or the native chat. */
  'orca:defaultSessionView',
  /** Legacy journal access for embedded pages served by older hosts. */
  'orca:mobileStructuredSendOperations:v1',
  /** The terminal's text scale, which pinch-to-zoom writes. */
  'orca:terminalTextScale',
  /** Whether the terminal's command inputs offer autocorrect. */
  'orca:terminalAutocompleteEnabled',
  /** Whether a terminal link opens in Orca's browser or the phone's. */
  'orca:terminalLinkOpenMode'
] as const

export const PAGE_STORAGE_KEY_PREFIXES = [
  /** `orca:pins:<hostId>`: the pinned worktrees of the host whose list the page is showing. */
  'orca:pins:',
  /** `orca:nativeChatTabs:<hostId>:<worktreeId>`: which tabs of one workspace show the chat. */
  'orca:nativeChatTabs:',
  /** `orca:terminalLiveInputDisabled:<hostId>:<worktreeId>`: the handles typing goes around. */
  'orca:terminalLiveInputDisabled:',
  /** Unsent command drafts, scoped to a host and workspace. */
  'orca:terminalDrafts:'
] as const

/** Long enough for a host's pinned ids, and far short of what a quota refuses. */
export const PAGE_STORAGE_MAX_VALUE_CHARS = 16 * 1024
export const PAGE_STORAGE_MAX_KEY_CHARS = 256
/** Every allowlisted key at once, which is what `init` carries. */
export const PAGE_STORAGE_MAX_ENTRIES = 32

export function isPageStorageKey(key: string): boolean {
  if (key.length > PAGE_STORAGE_MAX_KEY_CHARS) {
    return false
  }
  return (
    PAGE_STORAGE_EXACT_KEYS.some((allowed) => allowed === key) ||
    PAGE_STORAGE_KEY_PREFIXES.some((prefix) => key.startsWith(prefix) && key.length > prefix.length)
  )
}

/**
 * The workspace a page route names, or null for a route that names none.
 *
 * Two of the keys above are scoped to one workspace as well as one host, and both sides of the
 * bridge have to agree on which: the shell builds `init` from it and the page holds its writes to
 * it. Derived from the pathname rather than passed down, because the pathname is the one thing both
 * sides are given — the shell is handed the route it opened and the page reads the same route out
 * of `init`, and a second channel for the same fact is how the two would disagree.
 *
 * The session route is the only pattern with a workspace segment *and* keys of its own, so it is
 * the only one read here; the files, review and source-control routes carry a `worktreeId` and no
 * per-workspace key, and a route that grows one adds its pattern here beside this one.
 */
export function pageRouteWorkspace(
  pathname: string
): { hostId: string; worktreeId: string } | null {
  const segments = pathname.split('/')
  if (segments.length !== 5 || segments[0] !== '' || segments[1] !== 'h') {
    return null
  }
  if (segments[3] !== 'session') {
    return null
  }
  try {
    const hostId = decodeURIComponent(segments[2] ?? '')
    const worktreeId = decodeURIComponent(segments[4] ?? '')
    return hostId === '' || worktreeId === '' ? null : { hostId, worktreeId }
  } catch {
    // A stray `%` is not an escape. The route would have been refused upstream; answering null
    // here means the page is handed no workspace key rather than a key built from rubbish.
    return null
  }
}

const WORKSPACE_KEY_PREFIXES = [
  'orca:nativeChatTabs:',
  'orca:terminalLiveInputDisabled:',
  'orca:terminalDrafts:'
] as const

/** Workspace-scoped keys are built the same way, so the shape is written once. */
function workspaceScopedKey(prefix: string, hostId: string, worktreeId: string): string {
  return `${prefix}${encodeURIComponent(hostId)}:${encodeURIComponent(worktreeId)}`
}

/** A workspace-scoped key of this host, any workspace: what a host-area page may reach in-page.
 *  The encoded host id holds no `:`, so the scope cannot match another host's keys. */
export function isHostWorkspaceStorageKey(key: string, hostId: string): boolean {
  const scope = `${encodeURIComponent(hostId)}:`
  return (
    isPageStorageKey(key) &&
    WORKSPACE_KEY_PREFIXES.some(
      (prefix) => key.startsWith(prefix + scope) && key.length > prefix.length + scope.length
    )
  )
}

/**
 * The keys the shell reads out of the app's store and hands the page in `init`.
 *
 * Filtered through `isPageStorageKey` rather than trusted: a workspace id long enough to push its
 * key past `PAGE_STORAGE_MAX_KEY_CHARS` would otherwise put a key in `init` that the page's own
 * schema refines away, and the page refuses the whole frame rather than that one key.
 */
export function pageStorageKeysForRoute(hostId: string, routePathname: string): string[] {
  const workspace = pageRouteWorkspace(routePathname)
  const scoped =
    workspace === null || workspace.hostId !== hostId
      ? []
      : WORKSPACE_KEY_PREFIXES.map((prefix) =>
          workspaceScopedKey(prefix, hostId, workspace.worktreeId)
        )
  return [...PAGE_STORAGE_EXACT_KEYS, `orca:pins:${hostId}`, ...scoped].filter(isPageStorageKey)
}

/**
 * The allowlist narrowed to one session, which is the one every write is actually held to.
 *
 * `isPageStorageKey` answers for the shape, so `orca:pins:<any host>` passes it; a page opened for
 * one host could therefore rewrite another's pinned list, which is not a key it was ever handed.
 * The same holds one level further in for the two workspace-scoped keys: a session page opened on
 * one workspace must not rewrite another's chat tabs. What the page may write is exactly what it
 * was given, so this is that same list.
 */
export function isPageStorageKeyForRoute(
  key: string,
  hostId: string,
  routePathname: string,
  hostArea = false
): boolean {
  return (
    key.length <= PAGE_STORAGE_MAX_KEY_CHARS &&
    (pageStorageKeysForRoute(hostId, routePathname).includes(key) ||
      (hostArea && isHostWorkspaceStorageKey(key, hostId)))
  )
}

/**
 * Whether the page opened for this route may write this key, which is three refusals in one.
 *
 * Not this page's host or route, not a key it was ever told about, or one the shell could not hand
 * it for size (ruling 33.6). The last is the one the page cannot be trusted with: a document
 * served from an older desktop bundle does not read `storageOversize`, so an allowlisted key it
 * holds no value for would be written whole and replace what the device has. Decided here so the
 * host and the page's own shim answer the same question.
 */
export function pageMayWriteStorageKey(
  key: string,
  hostId: string,
  route: { pathname: string } | null,
  held: PageStorageForInit,
  hostArea = false
): boolean {
  return (
    route !== null &&
    isPageStorageKeyForRoute(key, hostId, route.pathname, hostArea) &&
    !held.storageOversize.includes(key)
  )
}

/** What `init` carries about the app's store: the values, and the keys it could not carry. */
export type PageStorageForInit = {
  storage: Readonly<Record<string, string>>
  storageOversize: readonly string[]
}

/**
 * The allowlisted values as `init` may carry them: nothing over the caps the page's schema refines
 * on, and the names of whatever was left out.
 *
 * The send journal is why this exists and is not a hypothetical. Measured on this tree: one entry
 * with no attachment costs 343 characters in the array — 342 of its own plus the comma that joins
 * it — so 47 unsettled sends measure 16,140 and 48 measure 16,483, past
 * `PAGE_STORAGE_MAX_VALUE_CHARS`, and the journal's own schema admits 4,096 of them. Handed to
 * `init` whole, the page's `BridgeInitStorageSchema` refuses the *frame* — not the key — and the
 * session screen never opens at all. Dropping the key instead leaves the page reading a default,
 * which is what `dropped` is for: a degradation the caller can name rather than a page that does
 * not start.
 *
 * `oversize` is the half of `dropped` the page must be told about, and it is a correctness matter
 * rather than a diagnostic one (ruling 33.6). A dropped key is still in
 * `pageStorageKeysForRoute`, so the page may write it — and for the journal that is destructive:
 * the page reads no journal, builds an empty one, and its first send writes a one-entry value over
 * the device's, losing every native entry and issuing a fresh `operationId` for an operation
 * native already holds. Named here, the page refuses the write instead. Only the value-cap drops
 * qualify: an entry-cap drop is a key that fits and did not make the frame, and the page's own
 * write of it is the same size the shell would have carried.
 */
export function pageStorageEntriesForInit(held: Readonly<Record<string, string>>): {
  entries: Record<string, string>
  dropped: string[]
  oversize: string[]
} {
  const entries: Record<string, string> = {}
  const dropped: string[] = []
  const oversize: string[] = []
  for (const [key, value] of Object.entries(held).reverse()) {
    if (value.length > PAGE_STORAGE_MAX_VALUE_CHARS) {
      dropped.push(key)
      oversize.push(key)
      continue
    }
    if (Object.keys(entries).length >= PAGE_STORAGE_MAX_ENTRIES) {
      dropped.push(key)
      continue
    }
    entries[key] = value
  }
  return { entries, dropped, oversize }
}

import { z } from 'zod'
import { MobileWebBundleErrorCodeSchema } from '../../../src/shared/mobile-web-bundle/bundle-rpc-contract'
import { joinUri } from './generation-cache-uri'
import type { GenerationFileSystem } from './generation-store-file-system'
import {
  MOBILE_WEB_SHELL_UPDATE_FAILURE_OUTCOMES,
  MOBILE_WEB_SHELL_UPDATE_FAILURE_REASONS,
  MOBILE_WEB_SHELL_UPDATE_FAILURE_WALLS,
  type MobileWebShellUpdateFailure
} from './mobile-web-shell-update-failure'

/**
 * The last few update failures per host, in the cache root beside the host index.
 *
 * Five per host: Troubleshoot shows the newest, and four behind it are enough to tell one bad
 * download from a host that fails every launch, while the file stays a few kilobytes.
 */
export const MAX_UPDATE_FAILURES_PER_HOST = 5
/** A ceiling across hosts too, because hosts are not otherwise bounded: six cached hosts' worth. */
export const MAX_UPDATE_FAILURES = 30

const UPDATE_FAILURE_LOG_FILE_NAME = 'update-failures.json'

/** Generation ids are sha256 hex; anything else is not recorded as one. */
const BUILD_ID_PATTERN = /^[a-f0-9]{64}$/

const BuildIdSchema = z.string().regex(BUILD_ID_PATTERN).nullable()

const UpdateFailureSchema = z
  .object({
    hostId: z.string().min(1).max(256),
    at: z.number().int().nonnegative(),
    reason: z.enum(MOBILE_WEB_SHELL_UPDATE_FAILURE_REASONS),
    hostCode: MobileWebBundleErrorCodeSchema.nullable(),
    offeredBuildId: BuildIdSchema,
    cachedBuildId: BuildIdSchema,
    outcome: z.enum(MOBILE_WEB_SHELL_UPDATE_FAILURE_OUTCOMES),
    wall: z.enum(MOBILE_WEB_SHELL_UPDATE_FAILURE_WALLS).nullable()
  })
  .strict()

/** A build id the host sent that is not a digest is dropped rather than kept: it is host text. */
function recordableBuildId(buildId: string | null): string | null {
  return buildId !== null && BUILD_ID_PATTERN.test(buildId) ? buildId : null
}

/** Oldest first. Appends, then evicts oldest-first: per host, then across hosts. */
export function appendUpdateFailure(
  entries: readonly MobileWebShellUpdateFailure[],
  failure: MobileWebShellUpdateFailure
): MobileWebShellUpdateFailure[] {
  const entry = {
    ...failure,
    offeredBuildId: recordableBuildId(failure.offeredBuildId),
    cachedBuildId: recordableBuildId(failure.cachedBuildId)
  }
  const all = [...entries, entry]
  const sameHost = all.filter((candidate) => candidate.hostId === entry.hostId)
  const evicted = new Set(
    sameHost.slice(0, Math.max(0, sameHost.length - MAX_UPDATE_FAILURES_PER_HOST))
  )
  const kept = all.filter((candidate) => !evicted.has(candidate))
  return kept.slice(Math.max(0, kept.length - MAX_UPDATE_FAILURES))
}

function logUri(fs: GenerationFileSystem): string {
  return joinUri(fs.rootUri, UPDATE_FAILURE_LOG_FILE_NAME)
}

/** Unreadable reads as empty, entry by entry: a diagnostic must never cost the shell anything. */
export async function readUpdateFailureLog(
  fs: GenerationFileSystem
): Promise<MobileWebShellUpdateFailure[]> {
  const text = await fs.readText(logUri(fs)).catch(() => null)
  if (text === null) {
    return []
  }
  let parsed: unknown
  try {
    parsed = JSON.parse(text)
  } catch {
    return []
  }
  if (!Array.isArray(parsed)) {
    return []
  }
  return parsed.flatMap((candidate: unknown) => {
    const entry = UpdateFailureSchema.safeParse(candidate)
    return entry.success ? [entry.data] : []
  })
}

async function writeUpdateFailureLog(
  fs: GenerationFileSystem,
  entries: readonly MobileWebShellUpdateFailure[]
): Promise<void> {
  if (entries.length === 0) {
    await fs.delete(logUri(fs))
    return
  }
  // Re-validated on the way out as well, so nothing but the listed fields ever reaches disk.
  const checked = entries.flatMap((entry) => {
    const valid = UpdateFailureSchema.safeParse(entry)
    return valid.success ? [valid.data] : []
  })
  await fs.writeText(logUri(fs), JSON.stringify(checked))
}

export async function recordUpdateFailureIn(
  fs: GenerationFileSystem,
  failure: MobileWebShellUpdateFailure
): Promise<void> {
  await writeUpdateFailureLog(fs, appendUpdateFailure(await readUpdateFailureLog(fs), failure))
}

export async function forgetHostUpdateFailuresIn(
  fs: GenerationFileSystem,
  hostId: string
): Promise<void> {
  const entries = await readUpdateFailureLog(fs)
  if (entries.length === 0) await fs.writeText(logUri(fs) + '.tmp', '[]')
  const kept = entries.filter((entry) => entry.hostId !== hostId)
  if (kept.length !== entries.length) {
    await writeUpdateFailureLog(fs, kept)
  }
}
